parameters.jsCode:
// Zwei Dinge passieren hier, bevor Geld fuer Tokens ausgegeben wird:
// 1. Pruefen, ob das PDF ueberhaupt eine Textebene hat. Ausschreibungen kommen oft als
//    eingescannter Papierstapel. Ohne diese Bremse bewertet die KI einen leeren String
//    und liefert eine formal saubere, inhaltlich frei erfundene Einschaetzung.
// 2. Kuerzen. Vergabeunterlagen haben gern 120 Seiten, davon sind 100 Formblaetter und AGB.
//    Der Anfang und das Ende enthalten in der Praxis Leistungsbeschreibung und Fristen.
const roh = String($input.first().json.text || '').replace(/\r/g, '');
const formular = $('Ausschreibung hochladen').first().json;

const text = roh.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
const MAX_ZEICHEN = 45000;

let gekuerzt = text;
let wurde_gekuerzt = false;
if (text.length > MAX_ZEICHEN) {
  const kopf = text.slice(0, Math.floor(MAX_ZEICHEN * 0.7));
  const fuss = text.slice(-Math.floor(MAX_ZEICHEN * 0.3));
  gekuerzt = kopf + '\n\n[... Mittelteil gekuerzt ...]\n\n' + fuss;
  wurde_gekuerzt = true;
}

return [{
  json: {
    projektname: formular['Projektname'] || formular.Projektname || '',
    auftraggeber: formular['Auftraggeber'] || formular.Auftraggeber || '',
    eingang: new Date().toISOString(),
    zeichen: text.length,
    lesbar: text.length >= 500,
    wurde_gekuerzt,
    text: gekuerzt,
  },
}];

values.content:
=Ausschreibung fuer das Projekt "{{ $json.projektname }}" von {{ $json.auftraggeber }}. Heutiges Datum: {{ $now.format('yyyy-MM-dd') }}.

