{{ $json.text }}

parameters.jsCode:
// Das Kompetenz-Sheet wird zu einem kompakten Profiltext verdichtet.
// Warum nicht die Rohtabelle in den Prompt: Leere Zellen und Spaltenrauschen lenken das
// Modell ab; ein sauber formulierter Fliesstext je Zeile liefert deutlich stabilere Urteile.
// Die Spalte "grenzen" ist die wichtigste - sie verhindert gruene Ampeln fuer Leistungen,
// die man zwar irgendwie anbieten koennte, aber nicht belastbar liefern kann.
const zeilen = $input.all().map((e) => e.json).filter((z) => z && (z.leistung || z.bereich));

if (zeilen.length === 0) {
  throw new Error('Das Sheet "Kompetenzen" ist leer — ohne eigenes Leistungsprofil ist kein Abgleich moeglich.');
}

const profil = zeilen.map((z, i) => {
  const teile = [];
  teile.push((i + 1) + '. Bereich: ' + (z.bereich || 'ohne Angabe'));
  teile.push('Leistung: ' + (z.leistung || 'ohne Angabe'));
  if (z.nachweis) teile.push('Nachweise/Referenzen: ' + z.nachweis);
  if (z.kapazitaet) teile.push('Kapazitaet: ' + z.kapazitaet);
  if (z.grenzen) teile.push('Ausdrueckliche Grenzen: ' + z.grenzen);
  return teile.join(' | ');
}).join('\n');

const analyse = $('Ausschreibung zerlegen').first().json;
const inhalt = analyse.message?.content ?? analyse;
const doku = $('Text vorbereiten').first().json;

return [{
  json: {
    projektname: doku.projektname,
    auftraggeber: doku.auftraggeber,
    eingang: doku.eingang,
    kompetenzprofil: profil,
    anzahl_kompetenzen: zeilen.length,
    ausschreibung: inhalt,
  },
}];

// Die Gesamtampel wird gerechnet, nicht vom Modell erfragt.
// Grund: Sprachmodelle neigen zu Wohlwollen ("passt teilweise" statt "passt nicht") und
// urteilen bei gleicher Datenlage nicht reproduzierbar. Eine feste Regel ist nachvollziehbar
// und im Zweifel gegenueber der Geschaeftsfuehrung begruendbar.
const roh = $input.first().json;
const bewertung = roh.message?.content ?? roh;
const basis = $('Kompetenzprofil aufbereiten').first().json;
const ausschreibung = basis.ausschreibung || {};

const anforderungen = Array.isArray(bewertung.anforderungen) ? bewertung.anforderungen : [];
const ausschluss = Array.isArray(bewertung.ausschlusskriterien) ? bewertung.ausschlusskriterien : [];

const zaehle = (liste, wert) => liste.filter((a) => String(a.bewertung || '').toLowerCase() === wert).length;
const gruen = zaehle(anforderungen, 'erfuellt');
const gelb = zaehle(anforderungen, 'teilweise');
const rot = zaehle(anforderungen, 'nicht erfuellt');
const gesamt = anforderungen.length || 1;

// Ein nicht erfuelltes Ausschlusskriterium beendet die Pruefung — Eignungs- und
// Ausschlusskriterien sind im Vergaberecht K.-o.-Kriterien, kein Verhandlungsspielraum.
const ausschlussVerletzt = ausschluss.filter((a) => String(a.bewertung || '').toLowerCase() !== 'erfuellt');

let ampel;
let begruendung;

if (ausschlussVerletzt.length > 0) {
  ampel = 'passt nicht';
  begruendung = 'Ausschlusskriterium nicht erfuellt: ' +
    ausschlussVerletzt.map((a) => a.kriterium + ' (' + (a.begruendung || 'ohne Begruendung') + ')').join('; ');
} else if (rot === 0 && gruen / gesamt >= 0.8) {
  ampel = 'passt';
  begruendung = gruen + ' von ' + gesamt + ' Anforderungen vollstaendig erfuellt, keine Luecken bei den Ausschlusskriterien.';
} else if (rot / gesamt > 0.3) {
  ampel = 'passt nicht';
  begruendung = rot + ' von ' + gesamt + ' Anforderungen koennen nicht erfuellt werden — der Aufwand fuer Nachunternehmer duerfte die Marge aufzehren.';
} else {
  ampel = 'passt teilweise';
  begruendung = gruen + ' erfuellt, ' + gelb + ' teilweise, ' + rot + ' offen. Mit Nachunternehmer oder Bietergemeinschaft machbar — vor der Abgabe klaeren.';
}

// Fristenpruefung: eine perfekt passende Ausschreibung, deren Abgabefrist in vier Tagen
// laeuft, ist praktisch trotzdem keine. Deshalb steht die Restlaufzeit gleichberechtigt oben.
const heute = new Date();
let tage_bis_abgabe = null;
const frist = (ausschreibung.fristen || []).find((f) => /abgabe|angebot|einreich/i.test(String(f.art || '')));
const fristDatum = frist && /^\d{4}-\d{2}-\d{2}$/.test(String(frist.datum || '')) ? new Date(frist.datum) : null;
if (fristDatum) {
  tage_bis_abgabe = Math.ceil((fristDatum - heute) / 86400000);
}

let fristhinweis = 'Keine eindeutige Abgabefrist im Dokument gefunden — bitte manuell pruefen.';
if (tage_bis_abgabe !== null) {
  if (tage_bis_abgabe < 0) fristhinweis = 'Abgabefrist ist bereits abgelaufen (' + frist.datum + ').';
  else if (tage_bis_abgabe <= 7) fristhinweis = 'Nur noch ' + tage_bis_abgabe + ' Tage bis zur Abgabe (' + frist.datum + ') — sofort entscheiden.';
  else fristhinweis = 'Noch ' + tage_bis_abgabe + ' Tage bis zur Abgabe (' + frist.datum + ').';
}

const zeile = (a) => '- [' + String(a.bewertung || '?').toUpperCase() + '] ' + a.anforderung + ': ' + (a.begruendung || '');

return [{
  json: {
    projektname: basis.projektname,
    auftraggeber: basis.auftraggeber,
    eingang: basis.eingang,
    ampel,
    begruendung,
    fristhinweis,
    tage_bis_abgabe,
    anzahl_anforderungen: anforderungen.length,
    erfuellt: gruen,
    teilweise: gelb,
    offen: rot,
    ausschluss_verletzt: ausschlussVerletzt.length,
    gegenstand: ausschreibung.gegenstand || '',
    auftragswert: ausschreibung.geschaetzter_auftragswert || 'nicht angegeben',
    detailliste: anforderungen.map(zeile).join('\n') || 'Keine Anforderungen erkannt.',
    ausschlussliste: ausschluss.map((a) => '- [' + String(a.bewertung || '?').toUpperCase() + '] ' + a.kriterium + ': ' + (a.begruendung || '')).join('\n') || 'Keine Ausschlusskriterien erkannt.',
    offene_punkte: (bewertung.offene_fragen || []).join(' | ') || 'keine',
  },
}];

